'use strict';
const reduced=matchMedia('(prefers-reduced-motion:reduce)');let paused=reduced.matches;const motion=document.querySelector('.motion');function applyMotion(){document.body.classList.toggle('paused',paused);document.documentElement.style.scrollBehavior=paused?'auto':'';motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?'▶ Motion':'Ⅱ Motion'}motion.onclick=()=>{paused=!paused;applyMotion()};applyMotion();reduced.addEventListener('change',e=>{paused=e.matches;applyMotion()});
const sections=[...document.querySelectorAll('main section[id]')],nav=[...document.querySelectorAll('.side-nav a')];const observe=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-15% 0px -55% 0px'});sections.forEach(e=>observe.observe(e));if(!sections.length)nav.forEach(a=>a.classList.toggle('active',a.hash==='#projects'));
const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){if(!paused)e.target.classList.add('reveal-in');reveal.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.section-title,.recognition-grid article,.about-grid article').forEach(e=>reveal.observe(e));
document.querySelector('.flower')?.addEventListener('click',e=>e.currentTarget.classList.toggle('bloom'));
document.querySelector('.copy-email')?.addEventListener('click',async()=>{const email='erangariprashanthreddy@gmail.com';const t=document.querySelector('.toast');try{await navigator.clipboard.writeText(email);t.textContent='Email copied to clipboard'}catch{t.textContent='Copy this email: '+email}t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),5000)});
document.querySelectorAll('[data-filter]').forEach(b=>{b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('[data-category]').forEach(c=>c.hidden=b.dataset.filter!=='All'&&c.dataset.category!==b.dataset.filter)};if(b.dataset.filter==='All')b.click()});
